Revise the ConcIR candidate for the same requirements. The requirements and the frozen contract are authoritative; the feedback is repair context.

<domain_requirements>
A waiter blocks on a condition variable until a predicate guarded by a mutex becomes true; a notifier makes it true and signals. The waiter must complete even if the signal arrives before it waits. On completion the program must print exactly one line `DONE ready=true` and then exit; it must terminate.
</domain_requirements>

<contract>
{
  "name": "bare-wait",
  "properties": [
    {
      "kind": "deadlock_free",
      "id": "no-deadlock"
    },
    {
      "kind": "reachability",
      "id": "ready-set",
      "goal": {
        "kind": "var_eq",
        "resource": "main::ready",
        "value": true
      }
    }
  ],
  "preserved": [
    {
      "kind": "reachable",
      "description": "main::waiter completes",
      "goal": {
        "kind": "function_completed",
        "function": "main::waiter"
      }
    },
    {
      "kind": "reachable",
      "description": "main::notifier completes",
      "goal": {
        "kind": "function_completed",
        "function": "main::notifier"
      }
    },
    {
      "kind": "reachable",
      "description": "main::ready == True",
      "goal": {
        "kind": "var_eq",
        "resource": "main::ready",
        "value": true
      }
    }
  ],
  "assumptions": {
    "sequential_consistency": true,
    "no_spurious_wakeups": true
  },
  "bounds": {
    "max_threads": 8,
    "max_frames_per_thread": 8,
    "max_states": 20000,
    "max_depth": 64,
    "max_boundary_events": 256
  },
  "allowed_scope": {
    "allow_lock_reorder": true
  }
}
</contract>

